mapper.select:
SELECT  COUNT(*)
  FROM T_AI_TRADE_LOG
 WHERE 1=1
   AND USER_ID    = #{userId}
   AND TRADE_DATE = #{tradeDate}

mapper.insert:
INSERT INTO T_AI_TRADE_LOG (
       USER_ID
      ,TRADE_DATE
      ,STATUS
      ,MARKET_VIEW
      ,DIARY
      ,ORDERS_JSON
      ,TOTAL_ASSET
      ,MESSAGE
) VALUES (
       #{userId}
      ,#{tradeDate}
      ,#{status}
      ,#{marketView}
      ,#{diary}
      ,#{ordersJson}
      ,#{totalAsset}
      ,#{message}
)
ON CONFLICT (USER_ID, TRADE_DATE) DO NOTHING
